import { profile } from '@/lib/portfolio-data';
import type { Metadata } from 'next';

/** Link-preview image generated by `app/opengraph-image.tsx`. */
const previewImage = '/opengraph-image';

/**
 * Consistent page metadata. A page's `openGraph`/`twitter` objects replace the parent's
 * entirely, so every page goes through here to keep the preview image and site name.
 */
export function pageMetadata({
  title,
  description,
  extra,
}: {
  title: string;
  description: string;
  extra?: Metadata;
}): Metadata {
  return {
    title,
    description,
    openGraph: {
      title,
      description,
      siteName: profile.name,
      locale: 'en_US',
      type: 'website',
      images: [previewImage],
    },
    twitter: { card: 'summary_large_image', title, description, images: [previewImage] },
    ...extra,
  };
}

/** "Page — Name" titles for inner pages. */
export const titleFor = (page: string) => `${page} — ${profile.name}`;
